import { useState, useEffect, useCallback, useRef } from "react";
import { Chessboard } from "react-chessboard";
import { Chess } from "chess.js";
import { io } from "socket.io-client";

// ─── Config ──────────────────────────────────────────────────────────────────
const SERVER_URL = process.env.REACT_APP_SERVER_URL || "http://localhost:3001";

// ─── Helpers ─────────────────────────────────────────────────────────────────
function formatClock(ms) {
  if (ms == null) return "--:--";
  const totalSec = Math.max(0, Math.ceil(ms / 1000));
  const m = Math.floor(totalSec / 60);
  const s = totalSec % 60;
  return `${String(m).padStart(2, "0")}:${String(s).padStart(2, "0")}`;
}

// ─── Inline styles (no external CSS deps) ───────────────────────────────────
const S = {
  root: {
    minHeight: "100vh",
    background: "#0d0d0f",
    color: "#e8e0d0",
    fontFamily: "'Georgia', 'Times New Roman', serif",
    display: "flex",
    flexDirection: "column",
    alignItems: "center",
    justifyContent: "center",
    padding: "16px",
    boxSizing: "border-box",
  },
  header: {
    fontSize: "13px",
    letterSpacing: "0.25em",
    textTransform: "uppercase",
    color: "#6b5f4b",
    marginBottom: "32px",
    display: "flex",
    alignItems: "center",
    gap: "12px",
  },
  headerLine: {
    flex: 1,
    height: "1px",
    background: "linear-gradient(90deg, transparent, #3a3228)",
    width: "60px",
  },

  // ── Lobby ─────────────────────────────────────────────────────────────────
  lobby: {
    display: "flex",
    flexDirection: "column",
    alignItems: "center",
    gap: "24px",
    maxWidth: "360px",
    width: "100%",
  },
  lobbyTitle: {
    fontSize: "42px",
    fontWeight: "400",
    color: "#e8e0d0",
    letterSpacing: "0.02em",
    margin: 0,
    textAlign: "center",
    lineHeight: 1.1,
  },
  lobbySubtitle: {
    fontSize: "13px",
    color: "#6b5f4b",
    letterSpacing: "0.15em",
    textTransform: "uppercase",
    textAlign: "center",
  },
  playerBadge: {
    background: "#1a1714",
    border: "1px solid #2e2820",
    borderRadius: "6px",
    padding: "10px 20px",
    fontSize: "14px",
    color: "#b8a98a",
    fontStyle: "italic",
  },
  tcGrid: {
    display: "grid",
    gridTemplateColumns: "1fr 1fr",
    gap: "10px",
    width: "100%",
  },
  tcBtn: (selected) => ({
    background: selected ? "#c8a96e" : "#1a1714",
    border: `1px solid ${selected ? "#c8a96e" : "#2e2820"}`,
    color: selected ? "#0d0d0f" : "#b8a98a",
    borderRadius: "6px",
    padding: "14px",
    fontSize: "16px",
    fontFamily: "Georgia, serif",
    cursor: "pointer",
    transition: "all 0.15s ease",
    display: "flex",
    flexDirection: "column",
    alignItems: "center",
    gap: "2px",
  }),
  tcLabel: { fontSize: "11px", letterSpacing: "0.1em", textTransform: "uppercase" },
  findBtn: {
    width: "100%",
    padding: "16px",
    background: "linear-gradient(135deg, #c8a96e 0%, #a07840 100%)",
    border: "none",
    borderRadius: "6px",
    color: "#0d0d0f",
    fontSize: "14px",
    letterSpacing: "0.2em",
    textTransform: "uppercase",
    fontFamily: "Georgia, serif",
    cursor: "pointer",
    transition: "opacity 0.15s",
  },

  // ── Waiting ───────────────────────────────────────────────────────────────
  waiting: {
    display: "flex",
    flexDirection: "column",
    alignItems: "center",
    gap: "20px",
    color: "#b8a98a",
  },
  spinner: {
    width: "40px",
    height: "40px",
    border: "2px solid #2e2820",
    borderTop: "2px solid #c8a96e",
    borderRadius: "50%",
    animation: "spin 1s linear infinite",
  },
  cancelBtn: {
    background: "transparent",
    border: "1px solid #2e2820",
    color: "#6b5f4b",
    padding: "10px 24px",
    borderRadius: "6px",
    cursor: "pointer",
    fontFamily: "Georgia, serif",
    fontSize: "13px",
    letterSpacing: "0.1em",
  },

  // ── Game ──────────────────────────────────────────────────────────────────
  game: {
    display: "flex",
    flexDirection: "column",
    alignItems: "center",
    gap: "8px",
    width: "100%",
    maxWidth: "520px",
  },
  playerRow: (active) => ({
    display: "flex",
    justifyContent: "space-between",
    alignItems: "center",
    width: "100%",
    padding: "10px 14px",
    background: active ? "#1e1a16" : "#131210",
    border: `1px solid ${active ? "#3a3228" : "#1e1a16"}`,
    borderRadius: "6px",
    transition: "all 0.2s ease",
  }),
  playerName: (active) => ({
    fontSize: "14px",
    color: active ? "#e8e0d0" : "#6b5f4b",
    fontStyle: "italic",
    display: "flex",
    alignItems: "center",
    gap: "8px",
  }),
  turnDot: {
    width: "7px",
    height: "7px",
    borderRadius: "50%",
    background: "#c8a96e",
    boxShadow: "0 0 6px #c8a96e",
  },
  clock: (active, low) => ({
    fontSize: "22px",
    fontVariantNumeric: "tabular-nums",
    letterSpacing: "0.05em",
    color: low ? "#e05252" : active ? "#c8a96e" : "#6b5f4b",
    fontFamily: "'Courier New', monospace",
    transition: "color 0.3s",
  }),
  boardWrap: {
    width: "100%",
    borderRadius: "4px",
    overflow: "hidden",
    boxShadow: "0 20px 60px rgba(0,0,0,0.8), 0 0 0 1px #2e2820",
  },
  statusBar: {
    fontSize: "12px",
    color: "#6b5f4b",
    letterSpacing: "0.12em",
    textTransform: "uppercase",
    minHeight: "20px",
  },
  actionRow: {
    display: "flex",
    gap: "8px",
    marginTop: "4px",
  },
  actionBtn: (variant) => ({
    padding: "8px 18px",
    border: `1px solid ${variant === "danger" ? "#6b2020" : "#2e2820"}`,
    borderRadius: "5px",
    background: "transparent",
    color: variant === "danger" ? "#e05252" : "#6b5f4b",
    fontSize: "12px",
    letterSpacing: "0.12em",
    textTransform: "uppercase",
    fontFamily: "Georgia, serif",
    cursor: "pointer",
    transition: "all 0.15s",
  }),

  // ── Game Over ─────────────────────────────────────────────────────────────
  overlay: {
    position: "fixed",
    inset: 0,
    background: "rgba(0,0,0,0.75)",
    display: "flex",
    alignItems: "center",
    justifyContent: "center",
    zIndex: 100,
    backdropFilter: "blur(4px)",
  },
  modal: {
    background: "#1a1714",
    border: "1px solid #2e2820",
    borderRadius: "10px",
    padding: "40px",
    textAlign: "center",
    maxWidth: "320px",
    width: "90%",
    display: "flex",
    flexDirection: "column",
    gap: "16px",
  },
  modalTitle: {
    fontSize: "28px",
    color: "#e8e0d0",
    margin: 0,
  },
  modalSub: {
    fontSize: "13px",
    color: "#6b5f4b",
    letterSpacing: "0.1em",
    textTransform: "uppercase",
  },
  playAgainBtn: {
    padding: "14px",
    background: "linear-gradient(135deg, #c8a96e 0%, #a07840 100%)",
    border: "none",
    borderRadius: "6px",
    color: "#0d0d0f",
    fontSize: "13px",
    letterSpacing: "0.2em",
    textTransform: "uppercase",
    fontFamily: "Georgia, serif",
    cursor: "pointer",
  },

  // ── Draw offer banner ─────────────────────────────────────────────────────
  drawBanner: {
    background: "#1e1a16",
    border: "1px solid #3a3228",
    borderRadius: "6px",
    padding: "12px 18px",
    display: "flex",
    alignItems: "center",
    gap: "12px",
    fontSize: "13px",
    color: "#b8a98a",
    width: "100%",
    boxSizing: "border-box",
  },
};

// ─── Keyframe injection ───────────────────────────────────────────────────────
const styleTag = document.createElement("style");
styleTag.textContent = `
  @keyframes spin { to { transform: rotate(360deg); } }
  @keyframes fadeIn { from { opacity: 0; transform: translateY(4px); } to { opacity: 1; transform: translateY(0); } }
  * { box-sizing: border-box; }
  body { margin: 0; }
`;
document.head.appendChild(styleTag);

// ─── App ──────────────────────────────────────────────────────────────────────
export default function App() {
  const socketRef = useRef(null);
  const chessRef = useRef(new Chess());   // local mirror for legal-move highlights

  const [phase, setPhase] = useState("lobby"); // lobby | waiting | game | ended
  const [myName, setMyName] = useState("");
  const [selectedTC, setSelectedTC] = useState(5);

  // Game state
  const [roomId, setRoomId] = useState(null);
  const [myColor, setMyColor] = useState("w");
  const [opponentName, setOpponentName] = useState("");
  const [fen, setFen] = useState("start");
  const [turn, setTurn] = useState("w");
  const [clocks, setClocks] = useState({ w: 0, b: 0 });
  const [status, setStatus] = useState("");
  const [gameOver, setGameOver] = useState(null);   // { reason, winner, winnerName }
  const [drawOffered, setDrawOffered] = useState(false);
  const [moveFrom, setMoveFrom] = useState(null);

  // ── Socket lifecycle ──────────────────────────────────────────────────────
  useEffect(() => {
    const socket = io(SERVER_URL, { transports: ["websocket"] });
    socketRef.current = socket;

    socket.on("assignedName", ({ name }) => setMyName(name));

    socket.on("waitingForOpponent", () => setPhase("waiting"));

    socket.on("queueCancelled", () => setPhase("lobby"));

    socket.on("gameStart", ({ roomId, color, opponentName, myName: mn, fen, timeControl, clocks, turn }) => {
      chessRef.current = new Chess();
      setRoomId(roomId);
      setMyColor(color);
      setOpponentName(opponentName);
      if (mn) setMyName(mn);
      setFen(fen);
      setTurn(turn);
      setClocks(clocks);
      setGameOver(null);
      setDrawOffered(false);
      setStatus(`${timeControl} min · ${color === "w" ? "You play White" : "You play Black"}`);
      setPhase("game");
    });

    socket.on("moveUpdate", ({ fen, turn, move, clocks }) => {
      chessRef.current.load(fen);
      setFen(fen);
      setTurn(turn);
      setClocks(clocks);
      setMoveFrom(null);
    });

    socket.on("clockUpdate", ({ clocks }) => {
      setClocks({ ...clocks });
    });

    socket.on("moveRejected", ({ reason }) => {
      setStatus(`Move rejected: ${reason}`);
    });

    socket.on("gameOver", ({ reason, winner, winnerName, clocks }) => {
      if (clocks) setClocks(clocks);
      setGameOver({ reason, winner, winnerName });
      setPhase("ended");
    });

    socket.on("drawOffered", () => setDrawOffered(true));
    socket.on("drawDeclined", () => setStatus("Draw offer declined."));

    return () => socket.disconnect();
  }, []);

  // ── Actions ───────────────────────────────────────────────────────────────
  const findGame = useCallback(() => {
    socketRef.current?.emit("findGame", { timeControl: selectedTC });
    setPhase("waiting");
  }, [selectedTC]);

  const cancelQueue = useCallback(() => {
    socketRef.current?.emit("cancelQueue");
  }, []);

  const resign = useCallback(() => {
    if (window.confirm("Resign this game?")) {
      socketRef.current?.emit("resign", { roomId });
    }
  }, [roomId]);

  const offerDraw = useCallback(() => {
    socketRef.current?.emit("offerDraw", { roomId });
    setStatus("Draw offered — awaiting response…");
  }, [roomId]);

  const acceptDraw = useCallback(() => {
    socketRef.current?.emit("acceptDraw", { roomId });
    setDrawOffered(false);
  }, [roomId]);

  const declineDraw = useCallback(() => {
    socketRef.current?.emit("declineDraw", { roomId });
    setDrawOffered(false);
  }, [roomId]);

  const playAgain = useCallback(() => {
    setPhase("lobby");
    setGameOver(null);
    setFen("start");
    chessRef.current = new Chess();
  }, []);

  // ── Move handling ─────────────────────────────────────────────────────────
  function onPieceDrop(sourceSquare, targetSquare, piece) {
    if (turn !== myColor) return false;

    const promotion =
      piece[1] === "P" &&
      ((myColor === "w" && targetSquare[1] === "8") ||
        (myColor === "b" && targetSquare[1] === "1"))
        ? "q"
        : undefined;

    socketRef.current?.emit("makeMove", {
      roomId,
      move: { from: sourceSquare, to: targetSquare, promotion },
    });
    return true; // Optimistic — board reverts if rejected via moveRejected
  }

  // ─── Render ───────────────────────────────────────────────────────────────
  const isMyTurn = phase === "game" && turn === myColor;
  const lowClockW = clocks.w < 10000;
  const lowClockB = clocks.b < 10000;

  // Player rows — opponent on top, me on bottom (standard orientation)
  const opponentColor = myColor === "w" ? "b" : "w";
  const opponentIsActive = turn === opponentColor;
  const meIsActive = turn === myColor;

  return (
    <div style={S.root}>
      {/* Keyframe styles already injected above */}

      {/* Header */}
      <div style={S.header}>
        <div style={S.headerLine} />
        ♟ Chess Arena
        <div style={{ ...S.headerLine, transform: "scaleX(-1)" }} />
      </div>

      {/* ── LOBBY ──────────────────────────────────────────────────────────── */}
      {phase === "lobby" && (
        <div style={S.lobby}>
          <h1 style={S.lobbyTitle}>Find a Game</h1>
          <p style={S.lobbySubtitle}>Real-time · Server validated</p>

          {myName && (
            <div style={S.playerBadge}>Playing as: {myName}</div>
          )}

          <div style={S.tcGrid}>
            {[1, 3, 5, 10].map((tc) => (
              <button
                key={tc}
                style={S.tcBtn(selectedTC === tc)}
                onClick={() => setSelectedTC(tc)}
              >
                <span style={{ fontSize: "24px" }}>{tc}</span>
                <span style={S.tcLabel}>min</span>
              </button>
            ))}
          </div>

          <button style={S.findBtn} onClick={findGame}>
            Find Opponent
          </button>
        </div>
      )}

      {/* ── WAITING ─────────────────────────────────────────────────────────── */}
      {phase === "waiting" && (
        <div style={S.waiting}>
          <div style={S.spinner} />
          <p>Seeking opponent for {selectedTC}min…</p>
          <button style={S.cancelBtn} onClick={cancelQueue}>
            Cancel
          </button>
        </div>
      )}

      {/* ── GAME ────────────────────────────────────────────────────────────── */}
      {(phase === "game" || phase === "ended") && (
        <div style={S.game}>

          {/* Opponent row */}
          <div style={S.playerRow(opponentIsActive)}>
            <span style={S.playerName(opponentIsActive)}>
              {opponentIsActive && <span style={S.turnDot} />}
              {opponentName}
            </span>
            <span style={S.clock(
              opponentIsActive,
              opponentColor === "w" ? lowClockW : lowClockB
            )}>
              {formatClock(clocks[opponentColor])}
            </span>
          </div>

          {/* Board */}
          <div style={S.boardWrap}>
            <Chessboard
              position={fen}
              onPieceDrop={onPieceDrop}
              boardOrientation={myColor === "w" ? "white" : "black"}
              arePiecesDraggable={isMyTurn && phase === "game"}
              customBoardStyle={{ borderRadius: "0" }}
              customDarkSquareStyle={{ backgroundColor: "#5a4a3a" }}
              customLightSquareStyle={{ backgroundColor: "#d4c5a9" }}
              animationDuration={120}
            />
          </div>

          {/* My row */}
          <div style={S.playerRow(meIsActive)}>
            <span style={S.playerName(meIsActive)}>
              {meIsActive && <span style={S.turnDot} />}
              {myName} (You)
            </span>
            <span style={S.clock(
              meIsActive,
              myColor === "w" ? lowClockW : lowClockB
            )}>
              {formatClock(clocks[myColor])}
            </span>
          </div>

          {/* Status */}
          <div style={S.statusBar}>{status}</div>

          {/* Draw banner */}
          {drawOffered && (
            <div style={S.drawBanner}>
              <span style={{ flex: 1 }}>Opponent offers a draw</span>
              <button style={S.actionBtn("default")} onClick={acceptDraw}>Accept</button>
              <button style={S.actionBtn("danger")} onClick={declineDraw}>Decline</button>
            </div>
          )}

          {/* Action buttons */}
          {phase === "game" && (
            <div style={S.actionRow}>
              <button style={S.actionBtn("default")} onClick={offerDraw}>
                Offer Draw
              </button>
              <button style={S.actionBtn("danger")} onClick={resign}>
                Resign
              </button>
            </div>
          )}
        </div>
      )}

      {/* ── GAME OVER OVERLAY ───────────────────────────────────────────────── */}
      {phase === "ended" && gameOver && (
        <div style={S.overlay}>
          <div style={S.modal}>
            {gameOver.winner === null ? (
              <>
                <h2 style={S.modalTitle}>Draw</h2>
                <p style={S.modalSub}>{gameOver.reason}</p>
              </>
            ) : gameOver.winner === myColor ? (
              <>
                <h2 style={{ ...S.modalTitle, color: "#c8a96e" }}>Victory</h2>
                <p style={S.modalSub}>{gameOver.reason}</p>
              </>
            ) : (
              <>
                <h2 style={{ ...S.modalTitle, color: "#6b5f4b" }}>Defeat</h2>
                <p style={S.modalSub}>{gameOver.reason}</p>
                {gameOver.winnerName && (
                  <p style={{ color: "#b8a98a", fontSize: "14px", margin: 0 }}>
                    {gameOver.winnerName} wins
                  </p>
                )}
              </>
            )}
            <button style={S.playAgainBtn} onClick={playAgain}>
              Play Again
            </button>
          </div>
        </div>
      )}
    </div>
  );
}
